class NumArray {
    private int[] bit, nums;
    private int n;
    public NumArray(int[] nums) {
        this.n = nums.length; this.nums = new int[n]; bit = new int[n + 1];
        for (int i = 0; i < n; i++) update(i, nums[i]);
    }
    public void update(int index, int val) {
        int delta = val - nums[index]; nums[index] = val;
        for (int i = index + 1; i <= n; i += i & (-i)) bit[i] += delta;
    }
    private int query(int i) {
        int sum = 0;
        for (i++; i > 0; i -= i & (-i)) sum += bit[i];
        return sum;
    }
    public int sumRange(int left, int right) {
        return query(right) - (left > 0 ? query(left - 1) : 0);
    }
}

class NumArray {
    private int[] tree;
    private int n;
    public NumArray(int[] nums) {
        n = nums.length;
        tree = new int[4 * n];
        build(nums, 1, 0, n - 1);
    }
    private void build(int[] nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
            return;
        }
        int mid = (start + end) / 2;
        build(nums, 2 * node, start, mid);
        build(nums, 2 * node + 1, mid + 1, end);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
    public void update(int index, int val) {
        updateHelper(1, 0, n - 1, index, val);
    }
    private void updateHelper(int node, int start, int end, int idx, int val) {
        if (start == end) {
            tree[node] = val;
            return;
        }
        int mid = (start + end) / 2;
        if (idx <= mid) updateHelper(2 * node, start, mid, idx, val);
        else updateHelper(2 * node + 1, mid + 1, end, idx, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
    public int sumRange(int left, int right) {
        return queryHelper(1, 0, n - 1, left, right);
    }
    private int queryHelper(int node, int start, int end, int l, int r) {
        if (l > end || r < start) return 0;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return queryHelper(2 * node, start, mid, l, r) + queryHelper(2 * node + 1, mid + 1, end, l, r);
    }
}
